import time as _time  # noqa: E402

_RAD_COLOR_PROPS = ("BackColor", "ForeColor")
_RAD_INT_PROPS = ("Left", "Top", "Width", "Height", "FontSize", "Value")


def _rad_rgb_hex(value):
    """'#rgb' / '#rrggbb' -> (r, g, b) or None."""
    s = str(value or "").strip()
    if not s.startswith("#"):
        return None
    s = s[1:]
    if len(s) == 3:
        s = "".join(ch * 2 for ch in s)
    try:
        return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4)) if len(s) >= 6 else None
    except ValueError:
        return None


def _rad_ease(f, ease):
    if ease == "in":
        return f * f
    if ease == "out":
        return 1 - (1 - f) * (1 - f)
    if ease == "inout":
        return 2 * f * f if f < 0.5 else 1 - 2 * (1 - f) * (1 - f)
    return f


def _rad_mix(prop, a, b, f, rgb):
    """Value of property *prop* between a (f = 0) and b (f = 1); rgb(colour) -> (r, g, b)."""
    if f <= 0:
        return a
    if f >= 1:
        return b
    if prop in _RAD_COLOR_PROPS:
        ca, cb = rgb(a), rgb(b)
        if ca is None or cb is None:
            return a
        return "#%02x%02x%02x" % tuple(max(0, min(255, int(round(x + (y - x) * f)))) for x, y in zip(ca, cb))
    if isinstance(a, bool) or isinstance(b, bool):
        return a
    try:
        x, y = float(a), float(b)
    except (TypeError, ValueError):
        return a                                   # Text...: discrete keyframes
    v = x + (y - x) * f
    return int(round(v)) if prop in _RAD_INT_PROPS else v


def _rad_value_at(prop, keys, t, start, rgb):
    """keys = [(ms, value, ease), ...] sorted by time; start = value before the first key."""
    if not keys:
        return start
    pts = list(keys)
    if pts[0][0] > 0 and start is not None:
        pts.insert(0, (0, start, ""))
    if t <= pts[0][0]:
        return pts[0][1]
    for (t0, v0, _e0), (t1, v1, e1) in zip(pts, pts[1:]):
        if t <= t1:
            f = (t - t0) / (t1 - t0) if t1 > t0 else 1.0
            return _rad_mix(prop, v0, v1, _rad_ease(f, e1), rgb)
    return pts[-1][1]


class _VisualStates:
    """Visual State Manager (Expression Blend). Controls switch automatically between Normal,
    MouseOver, Pressed, Focused and Disabled; GoToState("Name") moves the form to one of its
    custom states (GoToState("Normal") = back to the designed values); GoToState(state, "Button1")
    forces a state on one control (GoToState("Normal", "Button1") gives it back to the automatic states)."""
    AUTO = ("MouseOver", "Pressed", "Focused", "Disabled")

    def __init__(self, owner, io, controls, form_states):
        self._io = io
        self.Controls = controls            # {control: {state: {property: value}}}
        self.FormStates = form_states       # {state: {form property: value}}
        self.CurrentState = "Normal"
        self._flags, self._manual, self._saved, self._applied = {}, {}, {}, {}
        for name, states in controls.items():
            if any(s in states for s in self.AUTO):
                io.hook(name, self, "Disabled" in states)

    @property
    def States(self):
        names = list(self.FormStates)
        for states in self.Controls.values():
            names += [s for s in states if s not in self.AUTO and s not in names]
        return names

    def StateOf(self, control):
        """Automatic states active on *control* (e.g. {"MouseOver", "Pressed"})."""
        return set(self._flags.get(control, ()))

    def _wanted(self, name):
        out = {}
        cur = self.CurrentState
        if not name:
            return dict(self.FormStates.get(cur, {})) if cur != "Normal" else out
        st = self.Controls.get(name, {})
        if cur != "Normal":
            out.update(st.get(cur, {}))
        manual = self._manual.get(name)
        if manual:
            out.update(st.get(manual, {}))
            return out
        flags = self._flags.get(name, ())
        if "Disabled" in flags:
            out.update(st.get("Disabled", {}))
            return out
        for s in ("Focused", "MouseOver", "Pressed"):
            if s in flags:
                out.update(st.get(s, {}))
        return out

    def _update(self, name):
        want = self._wanted(name)
        for key in [k for k in self._applied if k[0] == name and k[1] not in want]:
            del self._applied[key]
            self._io.set(name, key[1], self._saved.pop(key, None))
            if key[1] in ("Left", "Top", "Width", "Height"):
                self._io.release(name, key[1])      # Anchor / Dock take the control back
        for prop, value in want.items():
            key = (name, prop)
            if key not in self._applied:
                self._saved[key] = self._io.get(name, prop)
            elif self._applied[key] == value:
                continue
            self._applied[key] = value
            self._io.set(name, prop, value)

    def Flag(self, name, state, on):
        flags = self._flags.setdefault(name, set())
        if (state in flags) == bool(on):
            return
        if on:
            flags.add(state)
        else:
            flags.discard(state)
        self._update(name)

    def GoToState(self, state, control=None):
        state = str(state or "Normal")
        if state == "Base":
            state = "Normal"
        if control:
            control = getattr(control, "_rad_name", control)
            if state == "Normal":
                self._manual.pop(control, None)
            else:
                self._manual[control] = state
            self._update(control)
            return True
        if state != "Normal" and state not in self.States:
            return False
        self.CurrentState = state
        for name in [""] + list(self.Controls):
            self._update(name)
        return True


class _Storyboard:
    """Storyboard (Expression Blend): keyframe animation of control properties.
    Begin() starts from time 0, Stop() stops and puts the animated properties back, Pause() / Resume(),
    Seek(ms); at the end the last values stay (HoldEnd) and the form's <Name>_Completed() runs.
    RepeatForever and AutoReverse can be changed before Begin()."""

    def __init__(self, owner, io, name, tracks, repeat=False, autoreverse=False):
        self._o, self._io, self.Name = owner, io, name
        self.Tracks = [(t, p, sorted(tuple(k) for k in keys)) for t, p, keys in tracks]
        self.RepeatForever, self.AutoReverse = bool(repeat), bool(autoreverse)
        self.Duration = max([k[0] for _t, _p, keys in self.Tracks for k in keys] or [0])
        self.IsPlaying, self.Position = False, 0
        self._gen, self._saved, self._t0, self._paused = 0, {}, 0.0, None

    def _remember(self):
        if not self._saved:
            self._saved = {(t, p): self._io.get(t, p) for t, p, _k in self.Tracks}

    def _apply(self, ms):
        self.Position = ms
        for t, p, keys in self.Tracks:
            v = _rad_value_at(p, keys, ms, self._saved.get((t, p)),
                              lambda c, t=t, p=p: self._io.rgb(t, p, c))
            self._io.set(t, p, v)

    def Begin(self):
        self._remember()
        self._gen += 1
        self.IsPlaying, self._paused = True, None
        self._t0 = _time.monotonic()
        self._tick(self._gen)

    def _tick(self, gen):
        if gen != self._gen or not self.IsPlaying:
            return
        ms = (_time.monotonic() - self._t0) * 1000.0
        span = self.Duration * (2 if self.AutoReverse else 1)
        done = False
        if span <= 0:
            ms, done = 0, True
        elif ms >= span:
            if self.RepeatForever:
                self._t0 += (ms // span) * span / 1000.0
                ms %= span
            else:
                ms, done = span, True
        self._apply(ms if ms <= self.Duration else span - ms)
        if done:
            self.IsPlaying = False
            fn = getattr(self._o, self.Name + "_Completed", None)
            if callable(fn):
                fn()
            return
        self._io.later(15, lambda: self._tick(gen))

    def Stop(self):
        self._gen += 1
        self.IsPlaying, self._paused, self.Position = False, None, 0
        for (t, p), v in self._saved.items():
            self._io.set(t, p, v)
            if p in ("Left", "Top", "Width", "Height"):
                self._io.release(t, p)          # Anchor / Dock take the control back
        self._saved = {}

    def Pause(self):
        if self.IsPlaying:
            self._gen += 1
            self.IsPlaying = False
            self._paused = _time.monotonic() - self._t0

    def Resume(self):
        if self._paused is not None:
            self._t0 = _time.monotonic() - self._paused
            self._paused = None
            self.IsPlaying = True
            self._gen += 1
            self._tick(self._gen)

    def Seek(self, ms):
        self._remember()
        ms = max(0, min(float(ms), self.Duration))
        self._apply(ms)
        if self.IsPlaying:
            self._t0 = _time.monotonic() - ms / 1000.0
        elif self._paused is not None:
            self._paused = ms / 1000.0


def _rad_records(data, root=""):
    """Records (dicts) of JSON data: a list, or the first list inside an object; root = dotted path."""
    for part in [p for p in str(root or "").split(".") if p]:
        if isinstance(data, dict):
            data = data.get(part)
        elif isinstance(data, list) and part.isdigit() and int(part) < len(data):
            data = data[int(part)]
        else:
            data = None
    if isinstance(data, dict):
        lists = [v for v in data.values() if isinstance(v, list)]
        data = lists[0] if lists else [data]
    if not isinstance(data, list):
        return []
    return [r if isinstance(r, dict) else {"value": r} for r in data]


def _rad_field(record, field):
    """record["a"]["b"] for field "a.b"; an empty field = the record's only (or "value") field."""
    if record is None:
        return None
    field = str(field or "").strip()
    if not field or field == "*":
        if isinstance(record, dict) and record:
            return record.get("value", next(iter(record.values())))
        return record
    cur = record
    for part in field.split("."):
        if isinstance(cur, dict):
            cur = cur.get(part)
        elif isinstance(cur, list) and part.isdigit() and int(part) < len(cur):
            cur = cur[int(part)]
        else:
            return None
    return cur


def _rad_text(v):
    if v is None:
        return ""
    if isinstance(v, bool):
        return "True" if v else "False"
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    if isinstance(v, (dict, list)):
        return _json.dumps(v, ensure_ascii=False)
    return str(v)


def _rad_convert(prop, v):
    if prop == "Value":
        try:
            return int(float(v))
        except (TypeError, ValueError):
            return 0
    if prop == "Checked":
        return v if isinstance(v, bool) else str(v).strip().lower() in ("1", "true", "yes", "on")
    return _rad_text(v)


class _DataSource:
    """A data source (JSON or CSV file): Records, Count, Position, Current, Fields, Load(),
    MoveFirst() / MoveNext() / MovePrevious() / MoveLast(), Value(field[, record])."""

    def __init__(self, owner, name, path, fmt="", root="", on_move=None):
        self.Name, self.Path, self.Root = name, path, root
        self.Format = (fmt or ("csv" if str(path).lower().endswith(".csv") else "json")).lower()
        self.Records, self.Error = [], ""
        self._pos, self._on_move = 0, on_move
        self.Load()

    def Load(self):
        try:
            if self.Format == "csv":
                with open(self.Path, newline="", encoding="utf-8-sig") as f:
                    self.Records = [dict(r) for r in _csv.DictReader(f)]
            else:
                with open(self.Path, encoding="utf-8-sig") as f:
                    self.Records = _rad_records(_json.load(f), self.Root)
            self.Error = ""
        except (OSError, ValueError) as e:
            self.Records, self.Error = [], str(e)
        self._pos = max(0, min(self._pos, len(self.Records) - 1))
        return self

    @property
    def Count(self):
        return len(self.Records)

    @property
    def Fields(self):
        out = []
        for r in self.Records:
            out += [k for k in r if k not in out]
        return out

    @property
    def Position(self):
        return self._pos

    @Position.setter
    def Position(self, index):
        index = max(0, min(int(index), len(self.Records) - 1)) if self.Records else 0
        if index != self._pos:
            self._pos = index
            if self._on_move is not None:
                self._on_move()

    @property
    def Current(self):
        return self.Records[self._pos] if self.Records else None

    def Value(self, field, record=None):
        return _rad_field(self.Current if record is None else record, field)

    def MoveFirst(self):
        self.Position = 0

    def MoveLast(self):
        self.Position = len(self.Records) - 1

    def MoveNext(self):
        self.Position = self._pos + 1

    def MovePrevious(self):
        self.Position = self._pos - 1


class _Bindings:
    """Control.Property <- source.field bindings; Refresh() applies them."""

    def __init__(self, owner, io, items):
        self._o, self._io = owner, io
        self.Items = [tuple(b) for b in items]
        for ctrl, prop, src, _field in self.Items:
            if prop == "Items":
                io.on_select(ctrl, lambda i, s=src: self._select(s, i))

    def _select(self, src, index):
        ds = getattr(self._o, src, None)
        if ds is not None and ds.Position != index:
            ds.Position = index

    def Refresh(self, source=None, lists=True):
        for ctrl, prop, src, field in self.Items:
            if source and src != source:
                continue
            ds = getattr(self._o, src, None)
            if ds is None:
                continue
            if prop == "Items":
                if lists:
                    self._io.set_items(ctrl, [_rad_text(ds.Value(field, r)) for r in ds.Records])
            elif prop == "Rows":
                if lists:
                    cols = [f.strip() for f in str(field or "").split(",") if f.strip()] or ds.Fields
                    self._io.set_rows(ctrl, cols, [[_rad_text(ds.Value(c, r)) for c in cols] for r in ds.Records])
            else:
                self._io.set(ctrl, prop, _rad_convert(prop, ds.Value(field)))


class _RadStateEvents(QObject):
    """Feeds MouseOver / Pressed / Focused / Disabled of one widget to the visual state manager."""

    def __init__(self, widget, name, vsm):
        super().__init__(widget)
        self.w, self.name, self.vsm = widget, name, vsm
        self.map = {QEvent.Type.Enter: ("MouseOver", True), QEvent.Type.Leave: ("MouseOver", False),
                    QEvent.Type.MouseButtonPress: ("Pressed", True),
                    QEvent.Type.MouseButtonRelease: ("Pressed", False),
                    QEvent.Type.FocusIn: ("Focused", True), QEvent.Type.FocusOut: ("Focused", False)}
        widget.installEventFilter(self)
        vp = getattr(widget, "viewport", None)
        if callable(vp):
            vp().installEventFilter(self)
        if not widget.isEnabled():
            vsm.Flag(name, "Disabled", True)

    def eventFilter(self, obj, ev):
        t = ev.type()
        if t == QEvent.Type.EnabledChange and obj is self.w:
            self.vsm.Flag(self.name, "Disabled", not self.w.isEnabled())
        elif t in self.map:
            state, on = self.map[t]
            self.vsm.Flag(self.name, state, on)
        return False


class _RadIO:
    """Reads / writes neutral properties of the Qt widgets (visual states, storyboards, bindings)."""

    def __init__(self, owner):
        self.o = owner
        self._colors, self._base_ss, self._events = {}, {}, []

    def w(self, name):
        return self.o if not name else getattr(self.o, name)

    def get(self, name, prop):
        try:
            w = self.w(name)
            if prop == "Text":
                if not name:
                    return w.windowTitle()
                if isinstance(w, QPlainTextEdit):
                    return w.toPlainText()
                if isinstance(w, QGroupBox):
                    return w.title()
                if isinstance(w, QComboBox):
                    return w.currentText()
                return w.text() if hasattr(w, "text") else ""
            if prop == "Left":
                return w.x()
            if prop == "Top":
                return w.y()
            if prop == "Width":
                return w.width()
            if prop == "Height":
                return w.height() - self._top() if not name else w.height()
            if prop in ("BackColor", "ForeColor"):
                return self._colors.get(name, {}).get(prop, "")
            if prop == "Visible":
                return not w.isHidden()
            if prop == "FontSize":
                return w.font().pointSize()
            if prop == "FontBold":
                return w.font().bold()
            if prop == "FontItalic":
                return w.font().italic()
            if prop == "Opacity":
                if not name:
                    return w.windowOpacity()
                eff = w.graphicsEffect()
                return eff.opacity() if isinstance(eff, QGraphicsOpacityEffect) else 1.0
            if prop == "Value":
                return w.value()
            if prop == "Checked":
                return w.isChecked()
        except (AttributeError, RuntimeError, TypeError):
            return None
        return None

    def _top(self):
        client = self.o.__dict__.get("_client")
        return self.o.height() - client.height() if client is not None else 0

    @staticmethod
    def _hold(name, w, prop):
        """A state / storyboard sets this geometry: Anchor / Dock leave it alone until release()."""
        if name:
            held = getattr(w, "_rad_held", None)
            if held is None:
                held = set()
                w._rad_held = held
            held.add(prop)

    def release(self, name, prop=None):
        """A state / storyboard gave the geometry back: Anchor / Dock place the control again."""
        if not name:
            return
        try:
            w = self.w(name)
            held = getattr(w, "_rad_held", None)
            if not held:
                return
            if prop is None:
                held.clear()
            else:
                held.discard(prop)
            host = w.parentWidget()
            for lay in (host.children() if host is not None else []):
                if type(lay).__name__ == "_Layout" and any(it[0] is w for it in lay.items):
                    lay.apply()
        except (AttributeError, RuntimeError):
            pass

    def set(self, name, prop, v):
        if v is None:
            return
        try:
            w = self.w(name)
            if prop == "Text":
                if not name:
                    w.setWindowTitle(str(v))
                elif isinstance(w, QPlainTextEdit):
                    w.setPlainText(str(v))
                elif isinstance(w, QGroupBox):
                    w.setTitle(str(v))
                elif isinstance(w, QComboBox):
                    if w.isEditable():
                        w.setEditText(str(v))
                    elif w.findText(str(v)) >= 0:
                        w.setCurrentIndex(w.findText(str(v)))
                elif hasattr(w, "setText"):
                    w.setText(str(v))
            elif prop in ("Left", "Top"):
                self._hold(name, w, prop)
                w.move(int(v) if prop == "Left" else w.x(), int(v) if prop == "Top" else w.y())
            elif prop in ("Width", "Height"):
                self._hold(name, w, prop)
                top = 0 if name else self._top()
                w.resize(int(v) if prop == "Width" else w.width(), int(v) + top if prop == "Height" else w.height())
            elif prop in ("BackColor", "ForeColor"):
                d = self._colors.setdefault(name, {})
                if v:
                    d[prop] = str(v)
                else:
                    d.pop(prop, None)
                self._restyle(name, w)
            elif prop == "Visible":
                w.setVisible(bool(v))
            elif prop in ("FontSize", "FontBold", "FontItalic"):
                f = w.font()
                if prop == "FontSize":
                    f.setPointSize(max(1, int(v)))
                elif prop == "FontBold":
                    f.setBold(bool(v))
                else:
                    f.setItalic(bool(v))
                w.setFont(f)
            elif prop == "Opacity":
                if not name:
                    w.setWindowOpacity(float(v))
                else:
                    eff = w.graphicsEffect()
                    if not isinstance(eff, QGraphicsOpacityEffect):
                        eff = QGraphicsOpacityEffect(w)
                        w.setGraphicsEffect(eff)
                    eff.setOpacity(max(0.0, min(1.0, float(v))))
            elif prop == "Value":
                w.setValue(int(float(v)))
            elif prop == "Checked":
                w.setChecked(bool(v))
        except (AttributeError, RuntimeError, TypeError, ValueError):
            pass

    def _restyle(self, name, w):
        if name not in self._base_ss:
            self._base_ss[name] = w.styleSheet()
        d = self._colors.get(name, {})
        rules = ""
        if d.get("BackColor"):
            rules += f"background-color:{d['BackColor']};"
        if d.get("ForeColor"):
            rules += f"color:{d['ForeColor']};"
        if not rules:
            w.setStyleSheet(self._base_ss[name])
            return
        if not w.objectName():
            w.setObjectName(name or "rad_form")
        sel = f"#{w.objectName()}" + (", #client" if not name else "")
        w.setStyleSheet(self._base_ss[name] + f"\n{sel} {{ {rules} }}")

    def set_items(self, name, items):
        w = self.w(name)
        w.clear()
        w.addItems([str(i) for i in items])

    def set_rows(self, name, columns, rows):
        w = self.w(name)
        w.clear()
        w.setColumnCount(max(1, len(columns)))
        w.setHorizontalHeaderLabels([str(c) for c in columns])
        w.setRowCount(len(rows))
        for r, row in enumerate(rows):
            for c, text in enumerate(row):
                w.setItem(r, c, QTableWidgetItem(str(text)))

    def rgb(self, name, prop, value):
        c = _rad_rgb_hex(value)
        if c is not None:
            return c
        if value:
            q = QColor(str(value))
        else:
            w = self.w(name)
            q = w.palette().color(w.backgroundRole() if prop == "BackColor" else w.foregroundRole())
        return (q.red(), q.green(), q.blue()) if q.isValid() else None

    def later(self, ms, fn):
        QTimer.singleShot(int(ms), self.o, fn)

    def on_select(self, name, fn):
        w = self.w(name)
        sig = w.currentRowChanged if isinstance(w, QListWidget) else w.currentIndexChanged
        sig.connect(lambda i: i >= 0 and fn(i))

    def hook(self, name, vsm, disabled=False):
        self._events.append(_RadStateEvents(self.w(name), name, vsm))


class Form1Designer(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setWindowTitle('IDE Blend')
        self.resize(400, 300)

        self.Button1 = QPushButton(self)
        self.Button1.setText('Button1')
        self.Button1.setGeometry(10, 10, 75, 23)
        _f = QFont('Segoe UI', 9); _f.setBold(False); _f.setItalic(False); self.Button1.setFont(_f)

        self.lstPeople = QListWidget(self)
        self.lstPeople.setGeometry(10, 50, 120, 95)
        _f = QFont('Segoe UI', 9); _f.setBold(False); _f.setItalic(False); self.lstPeople.setFont(_f)

        self.Label1 = QLabel(self)
        self.Label1.setText('Label1')
        self.Label1.setGeometry(200, 50, 60, 17)
        _f = QFont('Segoe UI', 9); _f.setBold(False); _f.setItalic(False); self.Label1.setFont(_f)
        self.Label1.setAlignment(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter)

        # Expression Blend: data sources and bindings, visual states, storyboards
        self._rad = _RadIO(self)
        self.SampleData1 = _DataSource(self, 'SampleData1', self._res('SampleData1.json'), '', '', on_move=lambda: self._bindings.Refresh('SampleData1', False))
        self._datasources = [self.SampleData1]
        self._bindings = _Bindings(self, self._rad, [['lstPeople', 'Items', 'SampleData1', 'Name'], ['Label1', 'Text', 'SampleData1', 'City']])
        self._bindings.Refresh()
        self._vsm = _VisualStates(self, self._rad, {'Button1': {'MouseOver': {'BackColor': '#3399FF', 'Text': 'Hovered'}}}, {})
        self.Storyboard1 = _Storyboard(self, self._rad, 'Storyboard1', [('Button1', 'Left', [(0, 10, ''), (1000, 250, '')]), ('Button1', 'Top', [(0, 10, ''), (600, 80, '')])], repeat=False, autoreverse=False)

        QTimer.singleShot(0, self._ev("Form1_Load"))
        QTimer.singleShot(0, self.Storyboard1.Begin)

    # ---------------------------------------------------------------- runtime
    def _ev(self, name):
        def call(*_a):
            fn = getattr(self, name, None)
            if fn is not None:
                fn()
        return call

    def _res(self, path):
        return os.path.join(os.path.dirname(os.path.abspath(__file__)), path)

    def closeEvent(self, event):
        e = EventArgs()
        fn = getattr(self, "Form1_FormClosing", None)
        if fn is not None:
            fn(e)
        if e.Cancel:
            event.ignore()
            return
        event.accept()
        fn = getattr(self, "Form1_FormClosed", None)
        if fn is not None:
            fn()

    # ---------------------------------------------------------------- Expression Blend

    def Refresh(self, reload=True):
        """Reload the data sources (JSON / CSV files) and apply the data bindings again."""
        if reload:
            for ds in self._datasources:
                ds.Load()
        self._bindings.Refresh()

    RefreshBindings = Refresh

    def GoToState(self, state, control=None):
        """Go to a visual state of the form ("Normal" = the designed values), or of one control."""
        return self._vsm.GoToState(state, control)
